def compute(vars):
    november_shares = vars["v1"]
    quarter_total_shares = vars["v2"]

    if quarter_total_shares == 0:
        return None

    percentage = november_shares / quarter_total_shares * 100

    return {
        "value": percentage,
        "trace": {
            "november_shares": november_shares,
            "quarter_total_shares": quarter_total_shares,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
